use hmac::{Hmac, Mac};
use kiln_adapter_github::events::DeliveryHeaders;
use kiln_core::{domain::Outcome, provider::CapabilityProfile, types::{EffectId, ExternalRef}, workflow::*};
use kiln_provider_api::{WorkflowPort, PortResult};
use kiln_web_service::{automation::AutomationProfile, engine::{Engine, Role}, profile::ServiceProfile};
use serde_json::{json, Value};
use sha2::Sha256;
use std::{collections::BTreeMap, fs, os::unix::fs::PermissionsExt, path::{Path, PathBuf}, process::Command};

// Deliberately controlled execution fixture: never connects a socket, starts a
// workload, or claims Lattice, confinement, or physical-host qualification.
struct ControlledPeer { profile: CapabilityProfile, root: PathBuf }
fn load(path: &Path) -> Value { serde_json::from_slice(&fs::read(path).unwrap()).unwrap() }
fn save(path: &Path, value: &Value) { fs::write(path, serde_json::to_vec_pretty(value).unwrap()).unwrap(); }
fn observation(plan: &WorkflowEffectPlan) -> WorkflowObservation {
    WorkflowObservation {
        effect_id: plan.effect_id.clone(), attempt_id: plan.attempt_id.clone(),
        candidate_id: plan.candidate_id.clone(), pipeline_revision_id: plan.pipeline_revision_id.clone(),
        workflow_policy_id: plan.workflow_policy_id.clone(), provider_profile: plan.provider_profile.clone(),
        idempotency_key: plan.idempotency_key.clone(),
        workflow: ExternalRef::new("lattice", "workflow", "controlled-origin-fixture").unwrap(),
        execution: ExternalRef::new("lattice", "execution", "controlled-blocker").unwrap(),
        sequence: 0, state: WorkflowState::Running, terminal: false,
        successful: false, outcome: Outcome::Pending,
        nodes: plan.nodes.iter().map(|node| WorkflowNodeObservation {
            node_id: node.id.clone(), state: WorkflowNodeState::Running, terminal: false, successful: false,
            adapter: ExternalRef::new("lattice", "adapter", "controlled-fixture").unwrap(), receipt: None,
        }).collect(), logs: vec![], receipt: None,
    }
}
impl ControlledPeer {
    fn record(&self, kind: &str) {
        let path = self.root.join("peer-counts.json");
        let mut counts = load(&path);
        counts[kind] = json!(counts[kind].as_u64().unwrap() + 1);
        save(&path, &counts);
    }
    fn plan(&self) -> WorkflowEffectPlan {
        serde_json::from_slice(&fs::read(self.root.join("peer-plan.json")).unwrap()).unwrap()
    }
}
impl WorkflowPort for ControlledPeer {
    fn profile(&self) -> &CapabilityProfile { &self.profile }
    fn dispatch(&mut self, plan: &WorkflowEffectPlan) -> PortResult<WorkflowObservation> {
        self.record("dispatches");
        fs::write(self.root.join("peer-plan.json"), serde_json::to_vec(plan).unwrap()).unwrap();
        Ok(observation(plan))
    }
    fn recover_dispatch(&mut self, plan: &WorkflowEffectPlan) -> PortResult<WorkflowObservation> {
        self.record("recoveries");
        assert_eq!(serde_json::to_value(plan).unwrap(), serde_json::to_value(self.plan()).unwrap());
        Ok(observation(plan))
    }
    fn observe(&mut self, id: &EffectId) -> PortResult<WorkflowObservation> {
        let plan = self.plan(); assert_eq!(id, &plan.effect_id); Ok(observation(&plan))
    }
    fn control(&mut self, _: &WorkflowControlRequest) -> PortResult<WorkflowObservation> {
        self.record("controls");
        panic!("origin scenario must never control the manual active execution")
    }
    fn reconcile(&mut self, id: &EffectId) -> PortResult<WorkflowObservation> { self.observe(id) }
    fn read_log(&mut self, _: &WorkflowLogReadRequest) -> PortResult<WorkflowLogChunk> {
        panic!("consumer never requests fixture logs")
    }
}
fn git(root: &Path, args: &[&str]) -> String {
    let result = Command::new("git").arg("-C").arg(root.join("source"))
        .args(args).env("GIT_CONFIG_NOSYSTEM", "1").env("GIT_CONFIG_GLOBAL", "/dev/null")
        .env("GIT_AUTHOR_NAME", "Disposable Origin Consumer")
        .env("GIT_AUTHOR_EMAIL", "origin@example.invalid")
        .env("GIT_COMMITTER_NAME", "Disposable Origin Consumer")
        .env("GIT_COMMITTER_EMAIL", "origin@example.invalid").output().unwrap();
    assert!(result.status.success(), "git {args:?}: {}", String::from_utf8_lossy(&result.stderr));
    String::from_utf8(result.stdout).unwrap().trim().to_owned()
}
fn commit(root: &Path, text: &str) -> String {
    fs::write(root.join("source/input.txt"), text).unwrap();
    git(root, &["add", "input.txt"]);
    git(root, &["-c", "commit.gpgsign=false", "commit", "-m", text]);
    git(root, &["rev-parse", "HEAD"])
}
fn request(engine: &mut Engine, method: &str, path: &str, body: Value, expected: u16) -> Value {
    let bytes = if method == "GET" { Vec::new() } else { serde_json::to_vec(&body).unwrap() };
    let response = engine.api(method, path, &bytes, Role::Operator).unwrap();
    let value: Value = serde_json::from_slice(&response.body).unwrap();
    assert_eq!(response.status, expected, "{method} {path}: {value}"); value
}
fn run(engine: &mut Engine, id: &Value) -> Value {
    request(engine, "GET", &format!("/api/runs/{}", id.as_str().unwrap()), Value::Null, 200)
}
fn open(root: &Path) -> Engine {
    let profile: ServiceProfile = serde_json::from_value(load(&root.join("profile.json"))).unwrap();
    let peer = ControlledPeer { profile: profile.projects[0].lattice(profile.bounds.max_runs).unwrap().provider, root: root.into() };
    let ports: BTreeMap<String, Box<dyn WorkflowPort + Send>> = BTreeMap::from([("fixture".into(), Box::new(peer) as Box<dyn WorkflowPort + Send>)]);
    let mut engine = Engine::open_with_ports(profile, ports).unwrap();
    let automation: AutomationProfile = serde_json::from_value(load(&root.join("automation.json"))).unwrap();
    engine.configure_automation(automation).unwrap(); engine
}
fn trigger(engine: &mut Engine, revision: &str, delivery: &str) -> Value {
    let body = serde_json::to_vec(&json!({"repository":{"id":42,"name":"source","full_name":"fixture/source","owner":{"login":"fixture"}},"ref":"refs/heads/main","after":revision,"deleted":false})).unwrap();
    let mut mac = Hmac::<Sha256>::new_from_slice(b"throwaway-origin-fixture-secret").unwrap();
    mac.update(&body);
    let signature: String = mac.finalize().into_bytes().iter().map(|b| format!("{b:02x}")).collect();
    let response = engine.automation_trigger("shared-origin", &DeliveryHeaders {delivery: delivery.into(), event: "push".into(), signature: format!("sha256={signature}")}, &body).unwrap();
    assert_eq!(response.status, 202, "{}", String::from_utf8_lossy(&response.body));
    serde_json::from_slice(&response.body).unwrap()
}
fn main() {
    let args: Vec<String> = std::env::args().collect();
    assert_eq!(args.len(), 3, "usage: kiln-origin-consumer prepare|deliver|verify ROOT");
    let root = Path::new(&args[2]);
    match args[1].as_str() {
        "prepare" => {
            fs::create_dir(root).unwrap();
            fs::set_permissions(root, fs::Permissions::from_mode(0o700)).unwrap();
            fs::create_dir(root.join("source")).unwrap();
            git(root, &["init", "--initial-branch=main"]);
            let revision = commit(root, "initial exact source");
            fs::write(root.join("trigger.secret"), b"throwaway-origin-fixture-secret").unwrap();
            fs::set_permissions(root.join("trigger.secret"), fs::Permissions::from_mode(0o600)).unwrap();
            save(&root.join("profile.json"), &json!({
                "schema":"kiln.web-service.v1","service_id":"origin-consumer","listen_address":"127.0.0.1:9443","origin":"https://localhost:9443",
                "tls":{"certificate_path":root.join("unused-cert.pem"),"private_key_path":root.join("unused-key.pem"),"min_version":"TLS1.3"},
                "operator_token_file":root.join("unused-operator.token"),"worker_token_file":root.join("unused-worker.token"),"state_directory":root.join("state"),
                "projects":[{"id":"fixture","label":"Disposable origin consumer","repository_path":root.join("source"),"reference":"refs/heads/main",
                    "source_limits":{"max_entries":32,"max_path_bytes":1024,"max_file_bytes":4096,"max_total_bytes":16384},
                    "workflow":{"socket_path":root.join("not-used.sock"),"allowed_user_ids":[unsafe {libc::geteuid()}],
                        "transport_limits":{"maximum_frame_bytes":1048576,"maximum_log_bytes":65536,"maximum_connections":4,"read_deadline_milliseconds":1000,"write_deadline_milliseconds":1000},
                        "adapter_limits":{"maximum_request_bytes":1048576,"maximum_response_bytes":1048576},"policy_id":"reviewed-policy","provider_profile_id":"reviewed-lattice","platform":"linux-x86_64",
                        "nodes":[{"id":"job","kind":"test","effect_class":"test","adapter_kind":"local","operation_identity":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}],"edges":[],
                        "controls":{"cancel":true,"pause":false,"resume":false},"bounds":{"max_nodes":8,"max_edges":16,"max_log_references":32,"max_log_read_bytes":4096,"max_total_log_bytes":65536}}}],
                "bounds":{"max_request_bytes":16384,"max_response_bytes":1048576,"max_header_bytes":4096,"max_connections":4,"timeout_seconds":2,"poll_interval_ms":10,"max_projects":2,"max_runs":16,"max_artifact_bytes":1024,"max_artifacts":2,"max_run_artifact_bytes":2048,"max_total_artifact_bytes":4096,"max_log_read_bytes":4096,"max_requests":64,"max_events_per_run":8,"max_state_bytes":1048576}
            }));
            save(&root.join("automation.json"), &json!({"schema":"kiln.web-automation.v1","max_records":100,"status_limit":20,"max_event_bytes":65536,"max_tick_effects":2,
                "triggers":[{"id":"shared-origin","project_id":"fixture","reference":"refs/heads/main","repository":{"owner":"fixture","repository":"source","repository_id":42,"allow_fork_pull_requests":false},"secret_file":root.join("trigger.secret"),"enabled":true,"push":true,"pull_request":false,"pull_request_base":"main","supersede_queued":true}],
                "schedules":[{"id":"shared-origin","project_id":"fixture","reference":"refs/heads/main","enabled":true,"interval_ms":3600000,"min_interval_ms":1000,"max_interval_ms":3600000,"next_due_ms":1}],"notifications":[]}));
            save(&root.join("peer-counts.json"), &json!({"dispatches":0,"controls":0,"recoveries":0}));
            let mut engine = open(root);
            request(&mut engine,"POST","/api/projects",json!({"project_id":"fixture","request_id":"consumer-enroll"}),200);
            let manual = request(&mut engine,"POST","/api/runs",json!({"project_id":"fixture","request_id":"manual-capacity-blocker"}),201);
            assert!(engine.tick_automation().unwrap().is_empty());
            let status = request(&mut engine,"GET","/api/automation",Value::Null,200);
            let source = status["sources"].as_array().unwrap().iter().find(|s| s["kind"] == "schedule").unwrap().clone();
            assert_eq!(source["registration_id"], "shared-origin");
            let schedule = run(&mut engine, &source["run_id"]);
            assert_eq!(schedule["phase"], "queued"); assert_eq!(schedule["source_revision"], revision);
            save(&root.join("prepared.json"), &json!({"manual":manual,"schedule":schedule,"schedule_source":source,"initial_revision":revision}));
            drop(engine);
            println!("{}",json!({"stage":"prepare","result":"queued schedule durably retained; process exits before webhook delivery","prepared":load(&root.join("prepared.json")),"peer":load(&root.join("peer-counts.json"))}));
        }
        "deliver" => {
            let prepared = load(&root.join("prepared.json"));
            let mut engine = open(root);
            assert_eq!(run(&mut engine,&prepared["schedule"]["id"]), prepared["schedule"]);
            assert_eq!(run(&mut engine,&prepared["manual"]["id"]), prepared["manual"]);
            let revision1 = commit(root,"first signed trigger source");
            let first = trigger(&mut engine,&revision1,"10000000-0000-4000-8000-000000000001");
            let first_run = run(&mut engine,&first["run_id"]);
            assert_eq!(first_run["phase"],"queued"); assert_eq!(first_run["source_revision"],revision1);
            assert_ne!(first_run["id"],prepared["schedule"]["id"]);
            assert_eq!(run(&mut engine,&prepared["schedule"]["id"]),prepared["schedule"]);
            drop(engine);
            {
                let connection = rusqlite::Connection::open(root.join("state/service.sqlite")).unwrap();
                let bytes: Vec<u8> = connection.query_row("SELECT state FROM service_state WHERE id=1", [], |r| r.get(0)).unwrap();
                let mut state: Value = serde_json::from_slice(&bytes).unwrap();
                let source = &mut state["automation"]["sources"][first["id"].as_str().unwrap()];
                source["status"] = json!("reserved");
                source["run_id"] = Value::Null;
                let prior = state["requests"].as_object_mut().unwrap().values_mut()
                    .find(|r| r["kind"] == "start" && r["resource"] == first["run_id"]).unwrap();
                prior["response"] = Value::Null;
                prior["status"] = json!(503);
                connection.execute("UPDATE service_state SET state=?1 WHERE id=1", [serde_json::to_vec(&state).unwrap()]).unwrap();
            }
            let mut engine = open(root);
            let revision2 = commit(root,"newer signed trigger source");
            let second = trigger(&mut engine,&revision2,"10000000-0000-4000-8000-000000000002");
            let newest = run(&mut engine,&second["run_id"]);
            let superseded = run(&mut engine,&first["run_id"]);
            assert_eq!(superseded["outcome"],"Cancelled");
            assert_eq!(superseded["superseded_by"],second["run_id"]);
            assert_eq!(superseded["superseded_revision"],revision2);
            assert_eq!(superseded["source_revision"],revision1);
            assert_eq!(newest["phase"],"queued"); assert_eq!(newest["source_revision"],revision2);
            assert_ne!(newest["id"],first["run_id"]);
            assert_eq!(run(&mut engine,&prepared["schedule"]["id"]),prepared["schedule"]);
            assert_eq!(run(&mut engine,&prepared["manual"]["id"]),prepared["manual"]);
            assert!(engine.tick_automation().unwrap().is_empty());
            let replayed_newest = run(&mut engine,&second["run_id"]);
            assert_eq!(replayed_newest["phase"], "queued");
            assert_eq!(replayed_newest["source_revision"], revision2);
            assert_ne!(replayed_newest["outcome"], "Cancelled");
            let status = request(&mut engine,"GET","/api/automation",Value::Null,200);
            let schedule_source = status["sources"].as_array().unwrap().iter().find(|s| s["id"] == prepared["schedule_source"]["id"]).unwrap();
            assert_eq!(schedule_source,&prepared["schedule_source"]);
            for id in [&first["run_id"],&second["run_id"]] {
                assert!(status["sources"].as_array().unwrap().iter().any(|s| s["kind"] == "trigger" && s["registration_id"] == "shared-origin" && &s["run_id"] == id));
            }
            let counts = load(&root.join("peer-counts.json"));
            assert_eq!(counts["dispatches"],1); assert_eq!(counts["controls"],0);
            let proof = json!({"durable_start_gap_exercised":true,"late_source_replay_exercised":true,"schedule":prepared["schedule"],"manual":prepared["manual"],"superseded":superseded,"newest":replayed_newest,"automation":status,"peer":counts});
            save(&root.join("delivered.json"),&proof);
            drop(engine);
            println!("{}",json!({"stage":"deliver","result":"same-id schedule unchanged; older trigger superseded by exact newer trigger; no execution controls","proof":proof}));
        }
        "verify" => {
            let proof = load(&root.join("delivered.json"));
            let mut engine = open(root);
            for key in ["manual","schedule","superseded","newest"] {
                assert_eq!(run(&mut engine,&proof[key]["id"]),proof[key],"persisted run {key}");
            }
            assert_eq!(load(&root.join("peer-counts.json"))["controls"],0);
            assert_eq!(git(root,&["rev-parse","HEAD"]),proof["newest"]["source_revision"].as_str().unwrap());
            let receipt = json!({"passed":true,"boundary":"Real Engine, native local Git source, signed trigger admission, durable on-disk state, three separate consumer processes. Controlled WorkflowPort only; no real Lattice, HTTPS listener, workload execution or host confinement qualification.","proof":proof});
            save(&root.join("receipt.json"),&receipt);
            println!("{receipt}");
        }
        _ => panic!("unknown stage"),
    }
}
